import numpy as np


class DifferentiableReasoner:
    """Perform differentiable logical reasoning over fuzzy truth values."""

    def __init__(self):
        pass

    def fuzzy_and(self, a, b):
        """Differentiable AND using product t-norm."""
        return a * b

    def fuzzy_or(self, a, b):
        """Differentiable OR using probabilistic sum."""
        return a + b - a * b

    def fuzzy_not(self, a):
        """Differentiable NOT: 1 - a."""
        return 1.0 - a

    def fuzzy_implies(self, a, b):
        """Differentiable implication: fuzzy_or(fuzzy_not(a), b)."""
        return 1.0 - a + a * b

    def fuzzy_equivalence(self, a, b):
        """Differentiable equivalence: AND(implies(a,b), implies(b,a))."""
        return self.fuzzy_and(self.fuzzy_implies(a, b), self.fuzzy_implies(b, a))

    def evaluate_formula(self, truth_values, formula):
        """Evaluate a logical formula with fuzzy truth values.

        Args:
            truth_values: dict mapping variable names to truth values [0,1]
            formula: string like 'AND(A, OR(B, NOT(C)))'
        """
        formula = formula.strip()

        if formula in truth_values:
            return truth_values[formula]

        if formula.startswith('NOT('):
            inner = self._extract_inner(formula)
            return self.fuzzy_not(self.evaluate_formula(truth_values, inner))

        if formula.startswith('AND('):
            args = self._extract_args(formula)
            result = self.evaluate_formula(truth_values, args[0])
            for arg in args[1:]:
                result = self.fuzzy_and(result, self.evaluate_formula(truth_values, arg))
            return result

        if formula.startswith('OR('):
            args = self._extract_args(formula)
            result = self.evaluate_formula(truth_values, args[0])
            for arg in args[1:]:
                result = self.fuzzy_or(result, self.evaluate_formula(truth_values, arg))
            return result

        if formula.startswith('IMPLIES('):
            args = self._extract_args(formula)
            return self.fuzzy_implies(
                self.evaluate_formula(truth_values, args[0]),
                self.evaluate_formula(truth_values, args[1])
            )

        raise ValueError(f"Unknown formula: {formula}")

    def _extract_inner(self, formula):
        """Extract content inside parentheses."""
        return formula[formula.index('(')+1:-1]

    def _extract_args(self, formula):
        """Split comma-separated arguments respecting nesting."""
        inner = self._extract_inner(formula)
        args = []
        depth = 0
        current = ""
        for char in inner:
            if char == '(':
                depth += 1
                current += char
            elif char == ')':
                depth -= 1
                current += char
            elif char == ',' and depth == 0:
                args.append(current.strip())
                current = ""
            else:
                current += char
        if current.strip():
            args.append(current.strip())
        return args

    def compute_reasoning_gradient(self, truth_values, formula, target=1.0):
        """Compute gradient of formula evaluation w.r.t. truth values."""
        epsilon = 1e-5
        gradients = {}

        base_value = self.evaluate_formula(truth_values, formula)
        loss = (base_value - target) ** 2

        for var in truth_values:
            perturbed = truth_values.copy()
            perturbed[var] += epsilon
            perturbed_value = self.evaluate_formula(perturbed, formula)
            perturbed_loss = (perturbed_value - target) ** 2

            gradients[var] = (perturbed_loss - loss) / epsilon

        return gradients, loss


if __name__ == "__main__":
    np.random.seed(42)
    reasoner = DifferentiableReasoner()

    values = {"A": 0.8, "B": 0.6, "C": 0.3}

    print("Fuzzy operations:")
    print(f"  AND(0.8, 0.6) = {reasoner.fuzzy_and(0.8, 0.6):.4f}")
    print(f"  OR(0.8, 0.6) = {reasoner.fuzzy_or(0.8, 0.6):.4f}")
    print(f"  NOT(0.8) = {reasoner.fuzzy_not(0.8):.4f}")
    print(f"  IMPLIES(0.8, 0.6) = {reasoner.fuzzy_implies(0.8, 0.6):.4f}")

    formula = "AND(A, OR(B, NOT(C)))"
    result = reasoner.evaluate_formula(values, formula)
    print(f"\nFormula: {formula}")
    print(f"Result: {result:.4f}")

    grads, loss = reasoner.compute_reasoning_gradient(values, formula)
    print(f"\nGradients: {grads}")
    print(f"Loss: {loss:.4f}")
